//                         Main application

void delay_us(unsigned int us) {
    // Convert microseconds us into how many clock ticks it will take 
    us *= SYS_FREQ / 1000000 / 2; // Core Timer updates every 2 ticks

    _CP0_SET_COUNT(0); // Set Core Timer count to 0

    while (us > _CP0_GET_COUNT()); // Wait until Core Timer count reaches the number we calculated earlier
}

//*****************************************************************************
//*****************************************************************************
// I2C_init() initialises I2C1 at at frequency of [frequency]Hz  

void I2C_init(double frequency) {
    double BRG;

    I2C1CON = 0; // Turn off I2C1 module
    I2C1CONbits.DISSLW = 0; // Disable slew rate for 100kHz

    BRG = (1 / (2 * frequency)) - 0.000000139;
    BRG *= (SYS_FREQ) - 2;

    I2C1BRG = (int) BRG; // Set baud rate
    I2C1CONbits.A10M = 0; // 7 bit slave address
    I2C1CONbits.ON = 1; // Turn on I2C1 module
}


// I2C_wait_for_idle() waits until the I2C peripheral is no longer doing anything  

void I2C_wait_for_idle(void) {
    uint16_t local_count = 0;
    while (I2C1CON & 0x1F); // Acknowledge sequence not in progress
    // Receive sequence not in progress
    // Stop condition not in progress
    // Repeated Start condition not in progress
    // Start condition not in progress
    //    while(I2C1STATbits.TRSTAT); // Bit = 0 ? Master transmit is not in progress
    do {
        local_count++;
        if (local_count > 65530) return;
    } while (I2C1STATbits.TRSTAT == 1); // Wait until ACK is received   
}

// I2C_start() sends a start condition  

void I2C_start() {
    I2C_wait_for_idle();
    I2C1CONbits.SEN = 1;
    while (I2C1CONbits.SEN == 1);
    I2C_wait_for_idle();
}

// I2C_stop() sends a stop condition  

void I2C_stop() {
    I2C_wait_for_idle();
    I2C1CONbits.PEN = 1;
}

// I2C_restart() sends a repeated start/restart condition

void I2C_restart() {
    I2C_wait_for_idle();
    I2C1CONbits.RSEN = 1;
    while (I2C1CONbits.RSEN == 1);
}

// I2C_ack() sends an ACK condition

void I2C_ack(void) {
    I2C_wait_for_idle();
    I2C1CONbits.ACKDT = 0; // Set hardware to send ACK bit
    I2C1CONbits.ACKEN = 1; // Send ACK bit, will be automatically cleared by hardware when sent  
    while (I2C1CONbits.ACKEN); // Wait until ACKEN bit is cleared, meaning ACK bit has been sent
}

// I2C_nack() sends a NACK condition

void I2C_nack(void) // Acknowledge Data bit
{
    I2C_wait_for_idle();
    I2C1CONbits.ACKDT = 1; // Set hardware to send NACK bit
    I2C1CONbits.ACKEN = 1; // Send NACK bit, will be automatically cleared by hardware when sent  
    while (I2C1CONbits.ACKEN); // Wait until ACKEN bit is cleared, meaning NACK bit has been sent
}

// address is I2C slave address, set wait_ack to 1 to wait for ACK bit or anything else to skip ACK checking  

void I2C_write(unsigned char address, char wait_ack, char RW) {
    uint16_t local_count = 0;
    I2C1TRN = address | RW; // Send slave address with Read/Write bit cleared
    //    LATBbits.LATB14 = 1;
    while (I2C1STATbits.TBF == 1) { // Wait until transmit buffer is empty
        //        while (I2C1STATbits.BCL == 1);
    }


    I2C_wait_for_idle(); // Wait until I2C bus is idle

    if (wait_ack) {
        do {
            local_count++;
            if (local_count > 65530) return;
        } while (I2C1STATbits.ACKSTAT == 1); // Wait until ACK is received   
    }

}
// value is the value of the data we want to send, set ack_nack to 0 to send an ACK or anything else to send a NACK  

void I2C_read(unsigned char *value, char ack_nack) {
    I2C1CONbits.RCEN = 1; // Receive enable
    while (I2C1CONbits.RCEN); // Wait until RCEN is cleared (automatic)  
    while (!I2C1STATbits.RBF); // Wait until Receive Buffer is Full (RBF flag)  
    *value = I2C1RCV; // Retrieve value from I2C1RCV

    if (!ack_nack) // Do we need to send an ACK or a NACK?  
        I2C_ack(); // Send ACK  
    else
        I2C_nack(); // Send NACK  
}


//******************************************************************************
/*        I2C data read from Sensirion SHT4xI Temp. and Humidity Sensor       */

/*
 * The following function will read the Sensirion Sensor data of Temperature
 * and Humidity on IC bus. The address code is factory configured to 0x44.
 */

void Temp_Hum_sensor() {

    delay_us(100);
    I2C_start(); /* Send start condition */
    I2C_write(0x44 << 1, 1, 0); /* Send address with ACK status, write = 0 */
    I2C_write(0xFD, 1, 0);
    I2C_stop();

    delay_us(7000); /* wait for 10ms as recommended in data sheet. */
    /* Start reading the sensor data */
    I2C_start();
    /* If conversion is still in progress the sensor do not send ACK. So, ACK will be checked here manually. */
    I2C_write(0x44 << 1, 1, 1); /* Send address with not ACK status, R/W = 1, means read data */

    I2C_read(&data_Global[1], 0); /* Read the Conversion MSB byte and ack it*/
    I2C_read(&data_Global[0], 0); /* Read the Conversion LSB byte and ack it*/
    I2C_read(&data_Global[2], 0); /* Read the Conversion LSB byte and  ack it (Temp. data checksum) */

    I2C_read(&data_Global[4], 0); /* Read the Conversion MSB byte and ack it*/
    I2C_read(&data_Global[3], 0); /* Read the Conversion LSB byte and ack it*/
    I2C_read(&data_Global[5], 1); /* Read the Conversion LSB byte and not ack it (humidity data checksum) */

    I2C_stop();

    /*
     * The following code will convert received data to Temperature in C and 
     * relative humidity as formulas given in sensor data sheet. 
     */

    /* Temperature Conversion*/
    //        ADC_val = data_Global[1]*256 + data_Global[0];
    //        ADC_val = -45 + (175 * ADC_val) / 65535; // In Centigrade
    //    sprintf(Temp_Humidity_Measured_Data_str[0], "%.1f", ADC_val); // Temp. in string format


    /* Relative Humidity Conversion*/
    ADC_val = data_Global[4]*256 + data_Global[3];
    ADC_val = -6 + (125 * ADC_val) / 65535; // In %RH
    //        sprintf(Temp_Humidity_Measured_Data_str[1], "%.1f", ADC_val); // %RH in string format

    /**********************Sending values through UART to DWIN Display*******************************/
    uint16_t t = ADC_val * 100; // multiplying by 100 will convert the float value to 16 bit integer

    // Extract MSB and LSB
    uint8_t msb = (t >> 8) & 0xFF; // Shift right by 8 bits and mask with 0xFF
    uint8_t lsb = t & 0xFF;

    data_to_display[6] = msb;
    data_to_display[7] = lsb;

    for (uint8_t i = 0; i < 8; i++) {
        UART2_Write(data_to_display[i]); /* Temp. data */
        delay_us(1000);
    }
}


// *****************************************************************************
// ************************ Power Supply Project *******************************

void enable_all_writeable_registors() {
    delay_us(100);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x10, 1, 0); // 0x10 Write enable register must set to 0x00 to enable write commands to writable registers
    I2C_write(0x00, 1, 0); // 0x00--> enables all writable registers
    I2C_stop(); // Sending stop bit to slave to stop communication
}

