// *****************************************************************************
//                  Code to turn ON power supply

void write_ON_on_power_supply_py(uint8_t on) {
    enable_all_writeable_registors();

    /*This block of code turn the power supply on or off according to need*/
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x01, 1, 0); // 0x01 OPERATION (ON, OFF Control)
    I2C_write(on, 1, 0); // 0x80: Turn ON, 0x00: Turn OFF
    I2C_stop(); // Sending stop bit to slave to stop communication
    //    delay_us(100);
}

// *****************************************************************************
//                  Code to turn OFF power supply

void write_OFF_on_power_supply_py(uint8_t off) {
    enable_all_writeable_registors();

    /*This block of code turn the power supply on or off according to need*/
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x01, 1, 0); // 0x01 OPERATION (ON, OFF Control)
    I2C_write(off, 1, 0); // 0x80: Turn ON, 0x00: Turn OFF
    I2C_stop(); // Sending stop bit to slave to stop communication
    //    delay_us(100);
}

// *****************************************************************************
//                  Code to turn FACTORY RESET power supply

void write_factory_reset_on_power_supply_py(uint8_t factory_reset) {

    enable_all_writeable_registors();

    /*Restore factory settings*/
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(factory_reset, 1, 0); // FACTORY RESET
    I2C_stop(); // Sending stop bit to slave to stop communication
    delay_us(1000);
}


// *****************************************************************************
// Code to set desired VOLTAGE and display the set VOLTAGE

void read_voltage_from_power_supply_py() {

    //    uint16_t read_voltage;

    /*Reading Output Voltage*/
    delay_us(700);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x8B, 1, 0); // 0x8B--> READ_VOUT
    //    delay_us(700);
    I2C_restart(); // Sending restart bit
    I2C_write(0xBE, 1, 1); // Sending Slave Address again, 1 to wait for acknowledge, 1 to read from slave
    I2C_read(&data_Global[0], 0); /* Reading LSB byte coming from Power Supply and ack it*/
    I2C_read(&data_Global[1], 1); /* Reading MSB byte coming from Power Supply and not ack it*/
    I2C_stop(); // Sending stop bit to slave to stop communication

    delay_us(100);
    UART2_Write('v');
    UART2_Write(data_Global[1]);
    UART2_Write(data_Global[0]);
}

void write_voltage_on_power_supply_py(uint8_t voltage_to_write) {

    enable_all_writeable_registors();

    /*Setting VOUT_COMMAND (Voltage Setting)*/
    delay_us(1000);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x21, 1, 0); // VOUT_COMMAND
    I2C_write(0x00, 1, 0); // sending LSB 
    I2C_write(voltage_to_write, 1, 0); // sending MSB (0x00 = 0V to 0xC8 = 200V)
    I2C_stop(); // Sending stop bit to slave to stop communication


    read_voltage_from_power_supply_py();
}

// *****************************************************************************
// Code to set desired CURRENT and display the set CURRENT

void read_current_from_power_supply_py() {

    /*Reading Output Current*/
    delay_us(700);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x46, 1, 0); // reading current
    I2C_restart(); // Sending restart bit
    I2C_write(0xBE, 1, 1); // Sending Slave Address again, 1 to wait for acknowledge, 1 to read from slave
    I2C_read(&data_Global[0], 0); /* Reading LSB byte coming from Power Supply and ack it*/
    I2C_read(&data_Global[1], 1); /* Reading MSB byte coming from Power Supply and not ack it*/
    I2C_stop(); // Sending stop bit to slave to stop communication

    delay_us(1000);
    UART2_Write('i');
    UART2_Write(data_Global[0]);
    UART2_Write(0x00);
}

void write_current_on_power_supply_py(uint8_t current_to_write) {

    enable_all_writeable_registors();

    /*Setting Current Limit*/
    delay_us(1000);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x46, 1, 0); // IOUT_OC_FAULT_LIMIT
    I2C_write(current_to_write, 1, 0); // sending LSB
    I2C_write(0x00, 1, 0); // sending MSB 
    I2C_stop(); // Sending stop bit to slave to stop communication

    read_current_from_power_supply_py();
}

// *****************************************************************************
// Code to set desired TEMPERATURE and display the set TEMPERATURE

void read_temperature_from_power_supply_py() {
    // check the read temperature register (Parameter to read)
    uint16_t read_temperature;

    /*Reading Temperature*/
    delay_us(700);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x8D, 1, 0); // reading temp of zone 1
    I2C_restart(); // Sending restart bit
    I2C_write(0xBE, 1, 1); // Sending Slave Address again, 1 to wait for acknowledge, 1 to read from slave
    I2C_read(&data_Global[0], 0); /* Reading LSB byte coming from Power Supply and ack it*/
    I2C_read(&data_Global[1], 1); /* Reading MSB byte coming from Power Supply and not ack it*/
    I2C_stop(); // Sending stop bit to slave to stop communication

    read_temperature = data_Global[1]*256 + data_Global[0];

    // Extract the 11 LSB
    uint16_t lsb_11_bits = read_temperature & 0x07FF; // Mask with 0x07FF (0000011111111111 in binary)
    //
    //    // Extract the 5 MSB
    uint16_t msb_5_bits = (read_temperature >> 11) & 0x001F; // Shift right by 11 and mask with 0x001F (0000000000011111 in binary)

    read_temperature = lsb_11_bits * (1 << msb_5_bits); // This is according to reference manual of power supply

    delay_us(1000);
    UART2_Write('t');
    UART2_Write(0x32);

}

void write_temperature_on_power_supply_py(uint8_t temperature_to_write) {
    read_temperature_from_power_supply_py();
}

// *****************************************************************************
// Code to set desired FAN SPEED and display the set FAN SPEED

void read_fan_speed_from_power_supply_py() {
    /*Reading Output Current*/
    delay_us(700);
    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x90, 1, 0); // reading current
    I2C_restart(); // Sending restart bit
    I2C_write(0xBE, 1, 1); // Sending Slave Address again, 1 to wait for acknowledge, 1 to read from slave
    I2C_read(&data_Global[0], 0); /* Reading LSB byte coming from Power Supply and ack it*/
    I2C_read(&data_Global[1], 1); /* Reading MSB byte coming from Power Supply and not ack it*/
    I2C_stop(); // Sending stop bit to slave to stop communication

    read_val_py = data_Global[1]*256 + data_Global[0];

    lsb_11_bits_py = read_val_py & 0x07FF;

    msb_5_bits_py = (read_val_py >> 11) & 0x001F;

    read_val_py1 = lsb_11_bits_py * (1 << msb_5_bits_py);

    delay_us(100);
}

void write_fan_speed_on_power_supply_py(uint8_t fan_speed_to_write) {

    enable_all_writeable_registors();

    I2C_start(); // Sending Start bit from microcontroller
    I2C_write(0xBE, 1, 0); // Sending Address, 1 to wait for acknowledge, 0 to write
    I2C_write(0x3B, 1, 0); // FAN_COMMAND_1_2
    I2C_write(fan_speed_to_write, 1, 0); // sending LSB (Writing 0 will leave the entire fan control to power supply)
    I2C_write(0x00, 1, 0); // sending MSB 
    I2C_stop(); // Sending stop bit to slave to stop communication
    delay_us(100);

    //    read_fan_speed_from_power_supply_py();
}

// ****************************************************************************
// ****************************************************************************
//                functionality selection function

void funcitonality_selector_py() {

    for (uint8_t i = 0; i < 2; i++) {
        data_from_display_py[i] = UART2_Read();
        delay_us(1000);
    }

    if (data_from_display_py[0] == 'O') { // ON
        write_ON_on_power_supply_py(data_from_display_py[1]);

    } else if (data_from_display_py[0] == 'X') { // OFF
        write_OFF_on_power_supply_py(data_from_display_py[1]);
    } else if (data_from_display_py[0] == 'V') { // Voltage Write
        write_voltage_on_power_supply_py(data_from_display_py[1]);
    } else if (data_from_display_py[0] == 'I') { // Current Write
        write_current_on_power_supply_py(data_from_display_py[1]);
    } else if (data_from_display_py[0] == 'F') { // Fan speed write
        write_fan_speed_on_power_supply_py(data_from_display_py[1]);
    } else if (data_from_display_py[0] == 'Q') { // Factory reset write
        write_factory_reset_on_power_supply_py(data_from_display_py[1]);
    }
}

